10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials", expression = "java(initials(owner))")
24	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
25	    @Mapping(target = "membershipTier", expression = "java(membershipTier(owner))")
26	    OwnerDto toOwnerDto(Owner owner);
27	
28	    /**
29	     * The upper-cased first letters of the first and last name, dot-separated with a
30	     * trailing dot, e.g. {@code J.S.}.
31	     */
32	    default String initials(Owner owner) {
33	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
34	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
35	    }
36	
37	    /**
38	     * The owner's membership number, formatted as {@code <customerCode>-M<YY>} where
39	     * {@code YY} is the last two digits of the registration date year, e.g.
40	     * {@code SMI-0007-M26}.
41	     */
42	    default String membershipNumber(Owner owner) {
43	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
44	        return owner.getCustomerCode() + "-M" + yy;
45	    }
46	
47	    /**
48	     * The owner's membership tier: {@code SILVER} when the owner has no namesakes
49	     * ({@code namesakeCount} is 0) and an email address is present, otherwise
50	     * {@code BRONZE}.
51	     */
52	    default String membershipTier(Owner owner) {
53	        boolean noNamesakes = Integer.valueOf(0).equals(owner.getNamesakeCount());
54	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
55	        return noNamesakes && hasEmail ? "SILVER" : "BRONZE";
56	    }
57	
58	    Owner toOwner(OwnerDto ownerDto);
59	
60	    @Mapping(target = "id", ignore = true)
61	    @Mapping(target = "pets", ignore = true)
62	    @Mapping(target = "customerCode", ignore = true)
63	    @Mapping(target = "householdId", ignore = true)
64	    @Mapping(target = "namesakeCount", ignore = true)
65	    Owner toOwner(OwnerFieldsDto ownerDto);
66	
67	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
68	
69	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
70	
71	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
72	        OwnerPageDto ownerPageDto = new OwnerPageDto();
73	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
74	        ownerPageDto.setPage(ownerPage.getNumber());
75	        ownerPageDto.setSize(ownerPage.getSize());
76	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
77	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
78	        return ownerPageDto;
79	    }
80	}
